namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Stands in for the provider's REST endpoint. Captures the single request sent by
/// <c>HttpPaymentGateway</c> and returns a pre-programmed response, so tests can assert
/// both what we send and how we interpret what comes back, without touching the network.
/// </summary>
internal sealed class StubHttpMessageHandler(HttpStatusCode statusCode, HttpContent? responseContent) : HttpMessageHandler
{
    public HttpRequestMessage? ReceivedRequest { get; private set; }

    public string? ReceivedBody { get; private set; }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        ReceivedRequest = request;
        ReceivedBody = request.Content is null ? null : await request.Content.ReadAsStringAsync(cancellationToken);

        return new HttpResponseMessage(statusCode) { Content = responseContent };
    }
}

