using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using Infrastructure = PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static readonly Money Amount = new(12m, "eur");

    [Fact]
    public async Task Sends_the_reference_and_amount_as_the_provider_expects()
    {
        var handler = new StubHttpMessageHandler(
            HttpStatusCode.OK,
            JsonContent("""{"status":"approved"}"""));
        var sut = new Infrastructure.HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });

        await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.ReceivedRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.ReceivedRequest.RequestUri!.AbsolutePath);

        using var body = JsonDocument.Parse(handler.ReceivedBody!);
        Assert.Equal("ORD-7", body.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12m, body.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", body.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_Approved()
    {
        var handler = new StubHttpMessageHandler(
            HttpStatusCode.OK,
            JsonContent("""{"status":"approved"}"""));
        var sut = new Infrastructure.HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_Declined()
    {
        var handler = new StubHttpMessageHandler(
            HttpStatusCode.OK,
            JsonContent("""{"status":"declined"}"""));
        var sut = new Infrastructure.HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_value_is_treated_as_Declined()
    {
        var handler = new StubHttpMessageHandler(
            HttpStatusCode.OK,
            JsonContent("""{"status":"pending"}"""));
        var sut = new Infrastructure.HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_is_read_as_the_provider_refusing_the_payment_outright()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.PaymentRequired, null);
        var sut = new Infrastructure.HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_error_status_is_not_swallowed_as_a_decline()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.InternalServerError, null);
        var sut = new Infrastructure.HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.test") });

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None));
    }

    private static StringContent JsonContent(string json) =>
        new(json, System.Text.Encoding.UTF8, "application/json");
}

